{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Viramidine, a ribonucleoside analog with a full ribose and a polar heterocyclic base, has 66.1% oral bioavailability in humans, directly supporting that the query's ribonucleoside scaffold can achieve F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Lamivudine, a polar nucleoside analog, has 87% oral bioavailability as an oral solution in humans, showing that high polarity does not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Zidovudine, a nucleoside reverse transcriptase inhibitor, has about 60% absolute oral bioavailability in patients, supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Didanosine, a purine dideoxynucleoside, has approximately 40% oral bioavailability in humans, demonstrating that purine nucleoside analogs can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Zalcitabine, a polar dideoxynucleoside, has a mean oral bioavailability of 88% in patients, strongly supporting high F for structurally related nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "In one patient study, didanosine had poor oral bioavailability (~19%±17%), providing threshold-relevant evidence that some polar nucleosides can fall below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar ribonucleoside analog, but direct human bioavailability data from closely related nucleoside analogs—didanosine (~40%), zalcitabine (88%), zidovudine (~60%), lamivudine (87%), and viramidine (66%)—consistently show F≥20%, often much higher. The few sub-20% didanosine values are dose/food-dependent and outweighed. Thus predict high bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the exact query molecule.",
    "Transporter substrate status (e.g., nucleoside transporters) for the query is not directly established.",
    "Impact of the very high H-bond donor count and ionization on absorption is inferred only from physicochemical estimates.",
    "First-pass metabolism and systemic clearance of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

